## Test the rarity boundary

The rarity result rests on one choice: the boundary that separates common taxa from rare taxa along the ranked abundance distribution. Our paper sets the boundary of common species as those representing the top 90% of baseline cover. 

Here we show that major patterns largely hold when move this boundary up or down the abundance distributions. Please try for yourself, and see how the primary statistics change.


```{shinylive-r}
#| standalone: true
#| viewerHeight: 760
#| viewerWidth: 1100

## file: app.R

library(shiny)
library(dplyr)

b64 <- paste(readLines("pre_b64.txt"), collapse = "")
pre <- unserialize(memDecompress(jsonlite::base64_dec(b64), "gzip"))

progs <- c("TCRMP", "VINPS", "CSUN")

palette_grp <- c(
  "Common.Broadcaster" = "#0072B2",
  "Rare.Broadcaster" = "#56B4E9",
  "Common.Brooder" = "#D55E00",
  "Rare.Brooder" = "#E69F00"
)

label_grp <- c(
  "Common.Broadcaster" = "Common broadcaster",
  "Rare.Broadcaster" = "Rare broadcaster",
  "Common.Brooder" = "Common brooder",
  "Rare.Brooder" = "Rare brooder"
)

term_labels <- c(
  "(Intercept)" = "Intercept",
  "yearind" = "Year",
  "categoryRare" = "Rarity",
  "Reproductive_modeBrooder" = "Repro. mode (Brooder)",
  "yearind:categoryRare" = "Year x Rarity",
  "yearind:Reproductive_modeBrooder" = "Year x Repro. mode",
  "categoryRare:Reproductive_modeBrooder" = "Rarity x Repro. mode",
  "yearind:categoryRare:Reproductive_modeBrooder" = "Year x Rarity x Repro. mode"
)

plot_sad <- function(prog, part) {
  d <- part$classification
  d <- d[order(prog$baseline$rank[match(d$taxon, prog$baseline$taxon)]), ]

  grp <- paste(d$commonness, d$Reproductive_mode, sep = ".")
  cols <- palette_grp[grp]
  cols[is.na(cols)] <- "grey70"

  op <- par(
    mar = c(3.2, 8.2, 2.2, 0.4),
    mgp = c(1.8, 0.5, 0),
    tcl = -0.25,
    cex.axis = 0.7,
    cex.lab = 0.8,
    cex.main = 0.88
  )
  on.exit(par(op))

  bp <- barplot(
    rev(d$meancov),
    horiz = TRUE,
    col = rev(cols),
    border = NA,
    names.arg = rev(d$taxon),
    las = 1,
    cex.names = 0.58,
    xlab = "Mean baseline abundance",
    main = sprintf("%d common / %d rare", part$n_common, prog$N - part$n_common)
  )

  nb <- nrow(d)

  if (part$n_common >= 1 && part$n_common < nb) {
    abline(
      h = mean(bp[c(nb - part$n_common, nb - part$n_common + 1)]),
      lty = 2,
      lwd = 1.5,
      col = "grey10"
    )
  }
}

plot_trend <- function(part) {
  d <- part$analysis

  grp <- paste(d$category, d$Reproductive_mode, sep = ".")
  cols <- palette_grp[grp]

  op <- par(
    mar = c(3.3, 3.2, 1.1, 0.3),
    mgp = c(1.8, 0.5, 0),
    tcl = -0.25,
    cex.axis = 0.72,
    cex.lab = 0.8
  )
  on.exit(par(op))

  plot(
    d$year,
    d$perccover,
    log = "y",
    pch = 21,
    cex = 0.68,
    bg = adjustcolor(cols, 0.32),
    col = "#00000055",
    xlab = "Year",
    ylab = "Abundance, log scale"
  )

  for (g in unique(grp)) {
    sub <- d[grp == g, ]

    if (nrow(sub) > 2) {
      m <- lm(log10(perccover) ~ year, sub)
      xs <- range(sub$year)
      ys <- 10^predict(m, data.frame(year = xs))
      lines(xs, ys, col = palette_grp[g], lwd = 1.7)
    }
  }

  legend(
    "topright",
    legend = label_grp[names(palette_grp)],
    col = palette_grp,
    lwd = 1.7,
    cex = 0.58,
    bty = "n",
    inset = 0.01
  )
}

part_of <- function(p, k) {
  pp <- pre[[p]]
  key <- as.character(min(max(round(k), min(pp$valid_k)), max(pp$valid_k)))
  pp$parts[[key]]
}

ui <- fluidPage(
  tags$style(HTML(
    "
    body {
