  )),

  #h4("Rare / common boundary explorer"),

  p(
    "Move each program's boundary. Taxa above the split are common, below are rare. "
  ),

  actionButton("reset", "Reset all to 90%"),

  tags$hr(),

  lapply(progs, function(p) {
    tagList(
      h5(sprintf("%s (%s)", p, pre[[p]]$taxon_level)),

      uiOutput(paste0("sl_", p)),

      tags$div(
        class = "plot-pair",

        tags$div(
          class = "plot-pane sad-pane",
          tags$div(
            class = "sad-inner",
            plotOutput(paste0("sad_", p), height = "300px", width = "300")
          )
        ),

        tags$div(
          class = "plot-pane trend-pane",
          tags$div(
            class = "trend-inner",
            plotOutput(paste0("trend_", p), height = "300px", width = "300px")
          )
        )
      ),

      tags$hr()
    )
  }),

  h5("Table 1, regenerated at the current boundaries"),
  uiOutput("table1"),

  h5("Supplemental: group-specific temporal slopes"),
  tableOutput("slopes")
)

server <- function(input, output, session) {
  po <- function(p) {
    part_of(p, input[[paste0("k_", p)]])
  }

  lapply(progs, function(p) {
    output[[paste0("sl_", p)]] <- renderUI({
      pp <- pre[[p]]

      sliderInput(
        paste0("k_", p),
        label = NULL,
        min = min(pp$valid_k),
        max = max(pp$valid_k),
        value = pp$k_paper,
        step = 1,
        width = "100%"
      )
    })

    output[[paste0("sad_", p)]] <- renderPlot({
      req(input[[paste0("k_", p)]])
      plot_sad(pre[[p]], po(p))
    })

    output[[paste0("trend_", p)]] <- renderPlot({
      req(input[[paste0("k_", p)]])
      plot_trend(po(p))
    })
  })

  observeEvent(input$reset, {
    for (p in progs) {
      updateSliderInput(session, paste0("k_", p), value = pre[[p]]$k_paper)
    }
  })

  output$table1 <- renderUI({
    req(input$k_TCRMP, input$k_VINPS, input$k_CSUN)

    parts <- lapply(progs, po)
    req(all(!vapply(parts, is.null, logical(1))))

    f2 <- function(x) {
      formatC(x, format = "f", digits = 2)
    }

    cell <- function(est, se, p) {
      st <- ifelse(
        p < 0.001,
        "***",
        ifelse(p < 0.01, "**", ifelse(p < 0.05, "*", ""))
      )

      pt <- ifelse(
        p < 0.001,
        "p<0.001",
        paste0("p=", formatC(p, format = "f", digits = 3))
      )

      HTML(paste0(f2(est), " (", f2(se), ")<br>", pt, st))
    }

    co1 <- parts[[1]]$coef

    body <- lapply(seq_len(nrow(co1)), function(i) {
      tags$tr(
        tags$td(term_labels[[co1$term[i]]]),
        lapply(seq_along(progs), function(j) {
          co <- parts[[j]]$coef
          sig <- co$p.value[i] < 0.05

          tags$td(
            style = if (sig) "font-weight:700" else "",
            cell(co$estimate[i], co$std.error[i], co$p.value[i])
          )
        })
      )
    })

    stat_labs <- c("Adj. R-squared", "Observations", "Residual SE", "df")

    stat_vals <- lapply(parts, function(pt) {
      fs <- pt$fit_stats

      c(
        formatC(fs$adj_r2, format = "f", digits = 3),
        fs$n,
        formatC(fs$rse, format = "f", digits = 3),
        fs$df
      )
    })

    stats <- lapply(seq_along(stat_labs), function(r) {
      tags$tr(
        tags$td(stat_labs[r]),
        lapply(stat_vals, function(v) tags$td(v[r]))
      )
    })

    tags$div(
      tags$table(
        class = "pubtbl",
        tags$thead(
          tags$tr(
            tags$th("Predictor"),
            lapply(progs, function(p) {
              tags$th(paste0(p, "\nEstimate (SE)\nP-value"))
            })
          )
        ),
        tags$tbody(body, stats)
      ),

      tags$p(
        style = "font-size:11px;color:#6d685e",
        "Table 1. Linear-model coefficients with HC3 robust standard errors. Dependent variable: ",
        "log10 percent cover. Significant terms (p<0.05) in bold."
      )
    )
  })

  output$slopes <- renderTable({
    req(input$k_TCRMP, input$k_VINPS, input$k_CSUN)

    do.call(
      rbind,
      lapply(progs, function(p) {
        po(p)$slopes %>%
          transmute(
            Program = p,
            Group,
            Slope = sprintf("%.4f", Slope),
            SE = sprintf("%.4f", SE),
            `Annual % change` = sprintf("%.2f", `Annual % change`),
            `P-value` = ifelse(
              `P-value` < 0.001,
              "< 0.001",
              sprintf("%.3f", `P-value`)
            )
          )
      })
    )
  },
  striped = TRUE,
  hover = TRUE,
  width = "100%")
}

shinyApp(ui, server)

